import type { AnalyticsEvent, AnalyticsOptions, PlayerState } from "../../core/types.js";

/** Receives vendor-neutral analytics events. */
export type AnalyticsSink = (event: AnalyticsEvent) => void;

/** Creates a safe analytics sink from player options. */
export function createAnalyticsSink(options: AnalyticsOptions): AnalyticsSink {
  return (event: AnalyticsEvent): void => {
    if (options.enabled === false) {
      return;
    }

    try {
      options.onEvent?.(event);
    } catch {
      // Analytics must never break playback.
    }
  };
}

/** Builds an analytics payload from a player state snapshot. */
export function toAnalyticsEvent(
  type: string,
  state: PlayerState,
  source: string | null,
  metadata?: Readonly<Record<string, unknown>>,
): AnalyticsEvent {
  return {
    type,
    at: Date.now(),
    position: state.currentTime,
    duration: state.duration,
    source,
    ...(metadata === undefined ? {} : { metadata }),
  };
}
